/* Generated by DVelop Work With Plus Pattern [Start] - Do not change */
// Exports the contents of a grid (using the selected order and filters) to an Excel file. LoadWWPContext.Call(&WWPContext)
Do 'OpenDocument'
&CellRow = 1 &FirstColumn = 1
Do 'LoadGridState'
Do 'WriteFilters'
Do 'WriteColumnTitles'
Do 'WriteData'
Do 'CloseDocument'
/* Generated by DVelop Work With Plus Pattern [End] - Do not change */
Sub 'OpenDocument'
/* Generated by DVelop Work With Plus Pattern [Start] - Do not change */
&Random = Random() * 10000 &Filename = WWP_GetDefaultExportPath() + !"trnsAreaEnsinoWWExport-" + &Random.ToString().Trim() + !".xlsx"
&ExcelDocument.Open(&Filename) Do 'CheckStatus' &ExcelDocument.Clear()
/* Generated by DVelop Work With Plus Pattern [End] - Do not change */
EndSub
Sub 'WriteFilters'
/* Generated by DVelop Work With Plus Pattern [Start] - Do not change */
If &GridState.DynamicFilters.Count >= 1 &GridStateDynamicFilter = &GridState.DynamicFilters.Item(1) &DynamicFiltersSelector1 = &GridStateDynamicFilter.Selected Do Case Case &DynamicFiltersSelector1 = !'AREENSNOME' &DynamicFiltersOperator1 = &GridStateDynamicFilter.Operator &AreEnsNome1.FromString(&GridStateDynamicFilter.Value) If not &AreEnsNome1.IsEmpty() &CellRow += 1 &ExcelDocument.Cells(&CellRow, &FirstColumn).Bold = True &ExcelDocument.Cells(&CellRow, &FirstColumn).Color = 3 Do Case Case &DynamicFiltersOperator1 = 0 &ExcelDocument.Cells(&CellRow, &FirstColumn).Text = format('%1 (%2)', "Nome", "WWP_FilterLike") Case &DynamicFiltersOperator1 = 1 &ExcelDocument.Cells(&CellRow, &FirstColumn).Text = format('%1 (%2)', "Nome", "WWP_FilterContains") EndCase &ExcelDocument.Cells(&CellRow, &FirstColumn + 1).Italic = True &ExcelDocument.Cells(&CellRow, &FirstColumn + 1).Text = WWP_Export_SecureText(&AreEnsNome1) EndIf EndCase If &GridState.DynamicFilters.Count >= 2 &DynamicFiltersEnabled2 = True &GridStateDynamicFilter = &GridState.DynamicFilters.Item(2) &DynamicFiltersSelector2 = &GridStateDynamicFilter.Selected Do Case Case &DynamicFiltersSelector2 = !'AREENSNOME' &DynamicFiltersOperator2 = &GridStateDynamicFilter.Operator &AreEnsNome2.FromString(&GridStateDynamicFilter.Value) If not &AreEnsNome2.IsEmpty() &CellRow += 1 &ExcelDocument.Cells(&CellRow, &FirstColumn).Bold = True &ExcelDocument.Cells(&CellRow, &FirstColumn).Color = 3 Do Case Case &DynamicFiltersOperator2 = 0 &ExcelDocument.Cells(&CellRow, &FirstColumn).Text = format('%1 (%2)', "Nome", "WWP_FilterLike") Case &DynamicFiltersOperator2 = 1 &ExcelDocument.Cells(&CellRow, &FirstColumn).Text = format('%1 (%2)', "Nome", "WWP_FilterContains") EndCase &ExcelDocument.Cells(&CellRow, &FirstColumn + 1).Italic = True &ExcelDocument.Cells(&CellRow, &FirstColumn + 1).Text = WWP_Export_SecureText(&AreEnsNome2) EndIf EndCase If &GridState.DynamicFilters.Count >= 3 &DynamicFiltersEnabled3 = True &GridStateDynamicFilter = &GridState.DynamicFilters.Item(3) &DynamicFiltersSelector3 = &GridStateDynamicFilter.Selected Do Case Case &DynamicFiltersSelector3 = !'AREENSNOME' &DynamicFiltersOperator3 = &GridStateDynamicFilter.Operator &AreEnsNome3.FromString(&GridStateDynamicFilter.Value) If not &AreEnsNome3.IsEmpty() &CellRow += 1 &ExcelDocument.Cells(&CellRow, &FirstColumn).Bold = True &ExcelDocument.Cells(&CellRow, &FirstColumn).Color = 3 Do Case Case &DynamicFiltersOperator3 = 0 &ExcelDocument.Cells(&CellRow, &FirstColumn).Text = format('%1 (%2)', "Nome", "WWP_FilterLike") Case &DynamicFiltersOperator3 = 1 &ExcelDocument.Cells(&CellRow, &FirstColumn).Text = format('%1 (%2)', "Nome", "WWP_FilterContains") EndCase &ExcelDocument.Cells(&CellRow, &FirstColumn + 1).Italic = True &ExcelDocument.Cells(&CellRow, &FirstColumn + 1).Text = WWP_Export_SecureText(&AreEnsNome3) EndIf EndCase EndIf EndIf EndIf If not (&TFAreEnsCodigo.IsEmpty() AND &TFAreEnsCodigo_To.IsEmpty()) WWP_ExportWriteFilter(&ExcelDocument, true, &CellRow, &FirstColumn, "Código") &ExcelDocument.Cells(&CellRow, &FirstColumn + 1).Number = &TFAreEnsCodigo WWP_ExportWriteFilter(&ExcelDocument, false, &CellRow, &FirstColumn + 2, "WWP_TSTo") &ExcelDocument.Cells(&CellRow, &FirstColumn + 3).Number = &TFAreEnsCodigo_To EndIf If not (&TFAreEnsNome_Sel.IsEmpty()) WWP_ExportWriteFilter(&ExcelDocument, true, &CellRow, &FirstColumn, "Nome") &ExcelDocument.Cells(&CellRow, &FirstColumn + 1).Text = WWP_Export_SecureText(&TFAreEnsNome_Sel) Else If not (&TFAreEnsNome.IsEmpty()) WWP_ExportWriteFilter(&ExcelDocument, true, &CellRow, &FirstColumn, "Nome") &ExcelDocument.Cells(&CellRow, &FirstColumn + 1).Text = WWP_Export_SecureText(&TFAreEnsNome) EndIf EndIf If not (&TFAreEnsSigla_Sel.IsEmpty()) WWP_ExportWriteFilter(&ExcelDocument, true, &CellRow, &FirstColumn, "Sigla") &ExcelDocument.Cells(&CellRow, &FirstColumn + 1).Text = WWP_Export_SecureText(&TFAreEnsSigla_Sel) Else If not (&TFAreEnsSigla.IsEmpty()) WWP_ExportWriteFilter(&ExcelDocument, true, &CellRow, &FirstColumn, "Sigla") &ExcelDocument.Cells(&CellRow, &FirstColumn + 1).Text = WWP_Export_SecureText(&TFAreEnsSigla) EndIf EndIf &CellRow += 2
/* Generated by DVelop Work With Plus Pattern [End] - Do not change */
EndSub
Sub 'WriteColumnTitles'
/* Generated by DVelop Work With Plus Pattern [Start] - Do not change */
&VisibleColumnCount = 0 If &Session.Get(!'trnsAreaEnsinoWWColumnsSelector') <> '' &ColumnsSelectorXML = &Session.Get(!'trnsAreaEnsinoWWColumnsSelector') &ColumnsSelector.FromXml(&ColumnsSelectorXML) Else Do 'InitializeColumnsSelector' EndIf
&ColumnsSelector.Columns.Sort(!'Order') For &ColumnsSelector_Column in &ColumnsSelector.Columns If &ColumnsSelector_Column.IsVisible = True &ExcelDocument.Cells(&CellRow, &FirstColumn + &VisibleColumnCount).Text = GetMessageText(iif(&ColumnsSelector_Column.DisplayName.IsEmpty(), &ColumnsSelector_Column.ColumnName, &ColumnsSelector_Column.DisplayName)) &ExcelDocument.Cells(&CellRow, &FirstColumn + &VisibleColumnCount).Bold = True &ExcelDocument.Cells(&CellRow, &FirstColumn + &VisibleColumnCount).Color = 11 &VisibleColumnCount += 1 EndIf EndFor
/* Generated by DVelop Work With Plus Pattern [End] - Do not change */
EndSub
Sub 'WriteData'
/* Generated by DVelop Work With Plus Pattern [Start] - Do not change */
For each trnsAreaEnsino order AreEnsNome when &OrderedBy = 1 AND &OrderedDsc = False order (AreEnsNome) when &OrderedBy = 1 AND &OrderedDsc = True order AreEnsCodigo when &OrderedBy = 2 AND &OrderedDsc = False order (AreEnsCodigo) when &OrderedBy = 2 AND &OrderedDsc = True order AreEnsSigla when &OrderedBy = 3 AND &OrderedDsc = False order (AreEnsSigla) when &OrderedBy = 3 AND &OrderedDsc = True
using trnsAreaEnsinoWWDS(&DynamicFiltersSelector1, &DynamicFiltersOperator1, &AreEnsNome1, &DynamicFiltersEnabled2, &DynamicFiltersSelector2, &DynamicFiltersOperator2 , &AreEnsNome2, &DynamicFiltersEnabled3, &DynamicFiltersSelector3, &DynamicFiltersOperator3, &AreEnsNome3, &TFAreEnsCodigo , &TFAreEnsCodigo_To, &TFAreEnsNome, &TFAreEnsNome_Sel, &TFAreEnsSigla, &TFAreEnsSigla_Sel) Where prefCodigo = &prefCodigo
// Write cell values &CellRow += 1
Do 'BeforeWriteLine' &VisibleColumnCount = 0 For &ColumnsSelector_Column in &ColumnsSelector.Columns If &ColumnsSelector_Column.IsVisible = True Do Case Case &ColumnsSelector_Column.ColumnName = !'AreEnsCodigo' &ExcelDocument.Cells(&CellRow, &FirstColumn + &VisibleColumnCount).Number = AreEnsCodigo Case &ColumnsSelector_Column.ColumnName = !'AreEnsNome' &ExcelDocument.Cells(&CellRow, &FirstColumn + &VisibleColumnCount).Text = WWP_Export_SecureText(AreEnsNome) Case &ColumnsSelector_Column.ColumnName = !'AreEnsSigla' &ExcelDocument.Cells(&CellRow, &FirstColumn + &VisibleColumnCount).Text = WWP_Export_SecureText(AreEnsSigla) EndCase &VisibleColumnCount += 1 EndIf EndFor
Do 'AfterWriteLine'
Endfor
/* Generated by DVelop Work With Plus Pattern [End] - Do not change */
EndSub
Sub 'CloseDocument'
/* Generated by DVelop Work With Plus Pattern [Start] - Do not change */
&ExcelDocument.Save() Do 'CheckStatus' &ExcelDocument.Close() &Session.Set(!'WWPExportFilePath', &Filename) &Session.Set(!'WWPExportFileName', !"trnsAreaEnsinoWWExport.xlsx") &Filename = WWP_DownloadReport.Link()
/* Generated by DVelop Work With Plus Pattern [End] - Do not change */
EndSub
Sub 'CheckStatus'
/* Generated by DVelop Work With Plus Pattern [Start] - Do not change */
If (&ExcelDocument.ErrCode <> 0) &Filename = "" &ErrorMessage = &ExcelDocument.ErrDescription &ExcelDocument.Close() Return EndIf
/* Generated by DVelop Work With Plus Pattern [End] - Do not change */
EndSub
Sub 'InitializeColumnsSelector'
/* Generated by DVelop Work With Plus Pattern [Start] - Do not change */
&ColumnsSelector = new WWPColumnsSelector() WWP_ColumnsSelector_Add(&ColumnsSelector, !"AreEnsCodigo", '', !'Código', True, '') WWP_ColumnsSelector_Add(&ColumnsSelector, !"AreEnsNome", '', !'Nome', True, '') WWP_ColumnsSelector_Add(&ColumnsSelector, !"AreEnsSigla", '', !'Sigla', True, '')
&UserCustomValue = LoadColumnsSelectorState.Udp(!'trnsAreaEnsinoWWColumnsSelector') If not(&UserCustomValue.IsEmpty()) &ColumnsSelectorAux.FromXml(&UserCustomValue) WWP_ColumnSelector_UpdateColumns(&ColumnsSelectorAux, &ColumnsSelector) EndIf
/* Generated by DVelop Work With Plus Pattern [End] - Do not change */
EndSub
Sub 'LoadGridState'
/* Generated by DVelop Work With Plus Pattern [Start] - Do not change */
// Load grid state from session. If &Session.Get(!"trnsAreaEnsinoWWGridState") = !"" &GridState.FromXml(LoadGridState.Udp(!"trnsAreaEnsinoWWGridState")) Else &GridState.FromXml(&Session.Get(!"trnsAreaEnsinoWWGridState")) Endif
&OrderedBy = &GridState.OrderedBy &OrderedDsc = &GridState.OrderedDsc
For &GridStateFilterValue in &GridState.FilterValues Do Case Case &GridStateFilterValue.Name = !"TFAREENSCODIGO" &TFAreEnsCodigo.FromString(&GridStateFilterValue.Value) &TFAreEnsCodigo_To.FromString(&GridStateFilterValue.ValueTo) Case &GridStateFilterValue.Name = !"TFAREENSNOME" &TFAreEnsNome.FromString(&GridStateFilterValue.Value) Case &GridStateFilterValue.Name = !"TFAREENSNOME_SEL" &TFAreEnsNome_Sel.FromString(&GridStateFilterValue.Value) Case &GridStateFilterValue.Name = !"TFAREENSSIGLA" &TFAreEnsSigla.FromString(&GridStateFilterValue.Value) Case &GridStateFilterValue.Name = !"TFAREENSSIGLA_SEL" &TFAreEnsSigla_Sel.FromString(&GridStateFilterValue.Value) EndCase EndFor
/* Generated by DVelop Work With Plus Pattern [End] - Do not change */
EndSub
Sub 'BeforeWriteLine'
/* Generated by DVelop Work With Plus Pattern [Start] - Do not change */
/* Generated by DVelop Work With Plus Pattern [End] - Do not change */
EndSub
Sub 'AfterWriteLine'
/* Generated by DVelop Work With Plus Pattern [Start] - Do not change */
/* Generated by DVelop Work With Plus Pattern [End] - Do not change */
EndSub

	/* Generated by DVelop Work With Plus Pattern [Start] - Do not change */

parm(out:&Filename, out:&ErrorMessage);

